document.addEventListener('DOMContentLoaded', function() {
  const catalogGrid = document.getElementById('catalogGrid');
  const catalogSearch = document.getElementById('catalogSearch');
  const searchCounter = document.getElementById('searchCounter');
  const filterBtns = document.querySelectorAll('.filter-btn');
  const langBtns = document.querySelectorAll('.lang-btn');
  const mobileToggle = document.getElementById('mobileMenuBtn');
  const mainNav = document.querySelector('.main-nav');
  
  const techModalBackdrop = document.getElementById('techModalBackdrop');
  const techModalClose = document.getElementById('techModalClose');
  const tmCloseBtn = document.getElementById('tmCloseBtn');
  const tmInquireBtn = document.getElementById('tmInquireBtn');
  
  const tmBadge = document.getElementById('tmBadge');
  const tmTitle = document.getElementById('tmTitle');
  const tmDesc = document.getElementById('tmDesc');
  const tmImg = document.getElementById('tmImg');
  const tmPower = document.getElementById('tmPower');
  const tmSpeeds = document.getElementById('tmSpeeds');
  const tmFrame = document.getElementById('tmFrame');
  const tmMaterial = document.getElementById('tmMaterial');
  const tmEfficiency = document.getElementById('tmEfficiency');
  const tmProtection = document.getElementById('tmProtection');
  const tmCooling = document.getElementById('tmCooling');
  const tmVoltage = document.getElementById('tmVoltage');
  const tmTableBody = document.getElementById('tmTableBody');

  let currentLang = localStorage.getItem('site_lang') || 'cz';

  function applyLanguage(lang) {
    currentLang = lang;
    localStorage.setItem('site_lang', lang);
    const dict = i18nDict[lang] || i18nDict.cz;

    document.querySelectorAll('[data-i18n]').forEach(el => {
      const key = el.getAttribute('data-i18n');
      if (dict[key]) {
        el.textContent = dict[key];
      }
    });

    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
      const key = el.getAttribute('data-i18n-placeholder');
      if (dict[key]) {
        el.setAttribute('placeholder', dict[key]);
      }
    });

    langBtns.forEach(btn => {
      btn.classList.toggle('active', btn.getAttribute('data-lang') === lang);
    });
  }

  langBtns.forEach(btn => {
    btn.addEventListener('click', function() {
      applyLanguage(this.getAttribute('data-lang'));
    });
  });

  applyLanguage(currentLang);

  if (mobileToggle && mainNav) {
    mobileToggle.addEventListener('click', function() {
      mainNav.classList.toggle('is-open');
    });
    mainNav.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => mainNav.classList.remove('is-open'));
    });
  }

  let activeFilter = 'all';

  function updateCatalogVisibility() {
    const query = (catalogSearch ? catalogSearch.value : '').toLowerCase().trim();
    let visibleCount = 0;
    const cards = document.querySelectorAll('.cat-card');

    cards.forEach(card => {
      const cat = card.getAttribute('data-category') || '';
      const text = card.textContent.toLowerCase();
      const matchesFilter = (activeFilter === 'all' || cat === activeFilter);
      const matchesQuery = (!query || text.includes(query));

      if (matchesFilter && matchesQuery) {
        card.style.display = '';
        visibleCount++;
      } else {
        card.style.display = 'none';
      }
    });

    if (searchCounter) {
      searchCounter.textContent = visibleCount;
    }
  }

  filterBtns.forEach(btn => {
    btn.addEventListener('click', function() {
      filterBtns.forEach(b => b.classList.remove('active'));
      this.classList.add('active');
      activeFilter = this.getAttribute('data-filter') || 'all';
      updateCatalogVisibility();
    });
  });

  if (catalogSearch) {
    catalogSearch.addEventListener('input', updateCatalogVisibility);
  }

  function openTechModal(itemId) {
    const item = catalogItemsData.find(it => it.id === itemId);
    if (!item) return;

    if (tmBadge) tmBadge.textContent = item.code;
    if (tmTitle) tmTitle.textContent = item.name;
    if (tmDesc) tmDesc.textContent = item.short_desc;
    if (tmImg) {
      tmImg.src = item.image;
      tmImg.alt = item.name;
    }
    if (tmPower) tmPower.textContent = item.power_range;
    if (tmSpeeds) tmSpeeds.textContent = item.speeds;
    if (tmFrame) tmFrame.textContent = item.frame_sizes;
    if (tmMaterial) tmMaterial.textContent = item.frame_material;
    if (tmEfficiency) tmEfficiency.textContent = item.efficiency;
    if (tmProtection) tmProtection.textContent = item.protection;
    if (tmCooling) tmCooling.textContent = item.cooling;
    if (tmVoltage) tmVoltage.textContent = item.voltage;

    if (tmTableBody) {
      tmTableBody.innerHTML = '';
      if (item.specs && item.specs.length) {
        item.specs.forEach(row => {
          const tr = document.createElement('tr');
          const typ = row.typ || row.puvodni || row.typ_radu || '-';
          const vykon = row.vykon || '-';
          const otacky = row.otacky || row.prevod || row.napajeni || '-';
          const vyska = row.vyska || row.nahrada || row.rozmery || '-';
          const proud = row.proud || row.brzda || row.ex_trida || row.max_moment || row.vystup || '-';
          const moment = row.moment || row.zona || row.ucel || row.rozbeh || row.hdel || row.komunikace || row.shoda || '-';
          const hmotnost = row.hmotnost || '-';

          tr.innerHTML = '<td><strong>' + typ + '</strong></td>' +
                         '<td>' + vykon + '</td>' +
                         '<td>' + otacky + '</td>' +
                         '<td>' + vyska + '</td>' +
                         '<td>' + proud + '</td>' +
                         '<td>' + moment + '</td>' +
                         '<td>' + hmotnost + '</td>';
          tmTableBody.appendChild(tr);
        });
      }
    }

    if (tmInquireBtn) {
      tmInquireBtn.setAttribute('data-target-model', item.name);
    }

    techModalBackdrop.style.display = 'flex';
    document.body.style.overflow = 'hidden';
  }

  function closeTechModal() {
    techModalBackdrop.style.display = 'none';
    document.body.style.overflow = '';
  }

  document.addEventListener('click', function(e) {
    const openBtn = e.target.closest('[data-open-tech], [data-tech-id]');
    if (openBtn) {
      e.preventDefault();
      const id = openBtn.getAttribute('data-tech-id') || openBtn.getAttribute('data-open-tech');
      openTechModal(id);
    }
    const mezInquireBtn = e.target.closest('[data-inquire]');
    if (mezInquireBtn) {
      const model = mezInquireBtn.getAttribute('data-inquire');
      const formMsg = document.getElementById('formMessage');
      const formCat = document.getElementById('formCategory');
      if (formCat) formCat.value = 'mez';
      if (formMsg) formMsg.value = 'Poptávám přímou náhradu SIEMENS za motor: ' + model;
    }
  });

  if (techModalClose) {
    techModalClose.addEventListener('click', closeTechModal);
  }
  if (tmCloseBtn) {
    tmCloseBtn.addEventListener('click', closeTechModal);
  }
  if (techModalBackdrop) {
    techModalBackdrop.addEventListener('click', function(e) {
      if (e.target === techModalBackdrop) {
        closeTechModal();
      }
    });
  }

  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && techModalBackdrop.style.display !== 'none') {
      closeTechModal();
    }
  });

  if (tmInquireBtn) {
    tmInquireBtn.addEventListener('click', function() {
      const model = this.getAttribute('data-target-model') || '';
      closeTechModal();
      const formMsg = document.getElementById('formMessage');
      if (formMsg) {
        formMsg.value = 'Dobrý den, poptávám technickou specifikaci a dostupnost motorové řady: ' + model;
      }
      const contactSection = document.getElementById('kontakt');
      if (contactSection) {
        contactSection.scrollIntoView({ behavior: 'smooth' });
      }
    });
  }

  const counters = document.querySelectorAll('.counter');
  const counterObserver = new IntersectionObserver((entries, observer) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const el = entry.target;
        observer.unobserve(el);
        const target = parseInt(el.getAttribute('data-target') || el.textContent, 10);
        if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
          return;
        }
        el.textContent = '0';
        const duration = 1200;
        const startTime = performance.now();
        const update = (now) => {
          const progress = Math.min((now - startTime) / duration, 1);
          const easeOut = 1 - Math.pow(1 - progress, 3);
          el.textContent = Math.floor(easeOut * target);
          if (progress < 1) {
            requestAnimationFrame(update);
          } else {
            el.textContent = target;
          }
        };
        requestAnimationFrame(update);
      }
    });
  }, { threshold: 0.2 });

  counters.forEach(c => counterObserver.observe(c));

  const revealObserver = new IntersectionObserver((entries, observer) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('revealed');
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.1 });

  document.querySelectorAll('.bento-box, .cat-card, .service-box, .contact-info-card, .contact-form-card').forEach(el => {
    el.classList.add('reveal-item');
    revealObserver.observe(el);
  });

  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('ref') === 'nabidka') {
    const heroPill = document.querySelector('.hero-pill');
    if (heroPill) {
      heroPill.classList.add('ref-highlight');
    }
  }
});
